{"file_path": "E:\Code\Claude\MyCCssh\Project\课题四\airway_zhuzhou\_diag_pair.py", "content": "# -*- coding: utf-8 -*-
"""诊断：正/反向航路对在水平面上是重合还是"似平行非平行"。

设计意图是同一条走廊上下叠放（水平完全重合、垂直分层），
若水平出现 20~300 m 的错位，就是最糟情况：既没重合、也没隔开。
"""
import json
import math
import os
import sys

sys.stdout.reconfigure(encoding="utf-8", errors="replace")
D = os.path.join(os.path.dirname(os.path.abspath(__file__)), "output", "airway")

with open(os.path.join(D, "SkywayNet_ZZ.json"), encoding="utf-8") as f:
    net = json.load(f)

R = {r["route_id"]: r for r in net["routes"]}


def xy(w):
    return (w["lon"] * 88600.0, w["lat"] * 111000.0)


def pts(r):
    return [xy(w) for w in r["geometry"]["waypoints"]]


def d_pt_seg(p, a, b):
    dx, dy = b[0] - a[0], b[1] - a[1]
    L2 = dx * dx + dy * dy
    if L2 < 1e-9:
        return math.hypot(p[0] - a[0], p[1] - a[1])
    t = max(0.0, min(1.0, ((p[0] - a[0]) * dx + (p[1] - a[1]) * dy) / L2))
    return math.hypot(p[0] - a[0] - t * dx, p[1] - a[1] - t * dy)


def d_to_poly(p, poly):
    return min(d_pt_seg(p, poly[i], poly[i + 1]) for i in range(len(poly) - 1))


print("正/反向航路对的水平错位（应当≈0，即上下完全重合）")
print("=" * 78)
print("%-8s %-8s %6s %6s %6s %6s   %s"
      % ("正向", "反向", "均值", "中位", "P90", "最大", "判定"))
bad = []
for rid, r in sorted(R.items()):
    rr = r.get("reverse_route_id")
    if not rr or rr not in R or rid > rr:
        continue
    A, B = pts(r), pts(R[rr])
    if len(A) < 2 or len(B) < 2:
        continue
    ds = sorted(d_to_poly(p, B) for p in A)
    mean = sum(ds) / len(ds)
    med = ds[len(ds) // 2]
    p90 = ds[int(len(ds) * 0.9)]
    mx = ds[-1]
    # 重合(<20m) 好；>300m 属于独立走廊也可接受；中间地带最糟
    if med < 20:
        tag = "重合 ✓"
    elif med > 300:
        tag = "独立走廊"
    else:
        tag = "★似平行非平行"
        bad.append((rid, rr, med))
    print("%-8s %-8s %6.0f %6.0f %6.0f %6.0f   %s"
          % (rid, rr, mean, med, p90, mx, tag))

print("=" * 78)
print("问题航路对 %d 组" % len(bad))
for a, b, m in bad:
    print("   %s / %s  中位错位 %.0f m  层：%s vs %s"
          % (a, b, m, R[a]["layer_id"], R[b]["layer_id"]))
"}

