"""确认：被"环岛过密"过滤掉的交叉口，是不是正向环岛的反向孪生？"""
import json
import math
import os
import sys

sys.stdout.reconfigure(encoding="utf-8", errors="replace")
D = os.path.join(os.path.dirname(os.path.abspath(__file__)), "output", "airway")


def load(n):
    with open(os.path.join(D, n), encoding="utf-8") as f:
        return json.load(f)


topo = load("SkywayTopology_ZZ.json")
net = load("SkywayNet_ZZ.json")
rg = load("[DBNAME_1].geojson")
J = {j["wp_id"]: j for j in topo["junctions"]}

ras = {}
for f in rg["features"]:
    if f["geometry"]["type"] == "LineString":
        p = f["properties"]
        ras[p["roundabout_id"]] = (p["center"]["lon"], p["center"]["lat"],
                                   p["layer_id"])

print("已建环岛：")
for k, v in ras.items():
    print("   %s  (%.5f,%.5f)  层=%s" % (k, v[0], v[1], v[2]))


def m(a, b, c, d):
    return math.hypot((a - c) * 88600.0, (b - d) * 111000.0)


print("\n被『环岛过密』过滤的交叉口，与已建环岛的关系：")
for wid in ("WP_J003", "WP_J006", "WP_J011", "WP_J014"):
    j = J.get(wid)
    if not j:
        continue
    lo, la = j["location"]["lon"], j["location"]["lat"]
    best = min(ras.items(), key=lambda kv: m(lo, la, kv[1][0], kv[1][1]))
    d = m(lo, la, best[1][0], best[1][1])
    print("  %s  航路=%-15s 层=%-6s → 距 %s 仅 %.0f m（%s 层）"
          % (wid, "×".join(j["routes"]), j.get("layers", ["?"])[0],
             best[0], d, best[1][2]))

print("\n结论：若『层』不同而水平位置相同，说明这是同一交叉的上下层孪生，")
print("      本应各自建环岛（垂直叠放），却被水平间距过滤误杀。")

# 正向已过环、反向未过环的航路对
print("\n正/反向过环状态对比：")
R = {r["route_id"]: r for r in net["routes"]}
for rid in sorted(R):
    r = R[rid]
    rr = r.get("reverse_route_id")
    if not rr or rid > (rr or ""):
        continue
    a = bool(r.get("roundabouts"))
    b = bool(R.get(rr, {}).get("roundabouts"))
    if a != b:
        print("  ★ %s 过环=%s  /  %s 过环=%s   ← 几何不对称，导致似平行非平行"
              % (rid, a, rr, b))
"}

