"""端到端验证：规划结果的轨迹是否真的沿环岛绕行（而非直穿弦线）。"""
import json
import math
import sys
import time
import urllib.request

sys.stdout.reconfigure(encoding="utf-8", errors="replace")
B = "http://127.0.0.1:8848"


def get(p):
    return json.load(urllib.request.urlopen(B + p, timeout=120))


def post(p, b):
    r = urllib.request.Request(B + p, data=json.dumps(b).encode(),
                               headers={"Content-Type": "application/json"})
    return json.load(urllib.request.urlopen(r, timeout=300))


for _ in range(20):
    try:
        get("/api/meta/health")
        break
    except Exception:
        time.sleep(2)

ras = get("/api/airway/roundabouts") if True else None
lst = ras.get("roundabouts", []) if isinstance(ras, dict) else ras
print("环岛 %d 个" % len(lst))
for r in lst:
    c = r["center"]
    print("   %s (%.5f,%.5f) R=%.0f 层=%s 接入=%s"
          % (r["roundabout_id"], c["lon"], c["lat"], r["radius_m"],
             r["layer_id"], "×".join(r["routes"])))


def d(lo1, la1, lo2, la2):
    return math.hypot((lo1 - lo2) * 88600.0, (la1 - la2) * 111000.0)


found = False
for o, dd in (("[PROJECT_5]", "VP04"), ("VP02", "VP05"), ("VP06", "VP03"),
              ("[PROJECT_5]", "VP05"), ("VP03", "[PROJECT_5]")):
    p = post("/api/plan", {"origin": o, "destination": dd})
    traj = p["trajectory"]
    segs = [s for s in p.get("legs", []) if
            s.get("edge_type") == "roundabout_arc"]
    ring_pts = {}
    for t in traj:
        for r in lst:
            c = r["center"]
            if abs(d(t["lon"], t["lat"], c["lon"], c["lat"])
                   - r["radius_m"]) < 30:
                ring_pts[r["roundabout_id"]] = \
                    ring_pts.get(r["roundabout_id"], 0) + 1
    print("\n%s→%s  %s  轨迹%d点  环岛航段%d"
          % (o, dd, p["summary"]["total_time_text"], len(traj), len(segs)))
    if ring_pts:
        found = True
        for k, v in ring_pts.items():
            print("   ★ 沿 %s 环周飞行 %d 个轨迹点" % (k, v))
    else:
        print("   （本次路径未经过环岛）")

print("\n" + "=" * 60)
print("结论：%s" % ("规划轨迹确实沿环岛绕行 ✓" if found
                 else "未观察到绕环，需继续排查 ✗"))
"}

